const binary = $input.item.binary || {};
const binaryKeys = Object.keys(binary);
let refKey = null;
let prodKeys = [];

for (const k of binaryKeys) {
  if (k.toLowerCase().includes('reference') || k.toLowerCase().includes('1.') || k.toLowerCase().includes('inspiration') || k === 'file_0') {
    if (!refKey) {
      refKey = k;
      continue;
    }
  }
  prodKeys.push(k);
}

if (!refKey && binaryKeys.length > 0) {
  refKey = binaryKeys[0];
  prodKeys = binaryKeys.slice(1);
}

const newBinary = {};

// 1. Rename Reference Image to inspired.png
if (refKey && binary[refKey]) {
  const orig = binary[refKey];
  const ext = orig.fileExtension || 'png';
  newBinary['inspired'] = {
    ...orig,
    fileName: `inspired.${ext}`
  };
}

// 2. Rename Product Images to product_1.ext, product_2.ext, etc.
prodKeys.forEach((k, idx) => {
  if (binary[k]) {
    const orig = binary[k];
    const ext = orig.fileExtension || (orig.mimeType ? orig.mimeType.split('/')[1] : 'png');
    const keyName = `product_${idx + 1}`;
    newBinary[keyName] = {
      ...orig,
      fileName: `product_${idx + 1}.${ext}`
    };
  }
});

const refBinary = newBinary['inspired'];
const refBase64 = refBinary ? refBinary.data : '';
const refMime = refBinary ? (refBinary.mimeType || 'image/png') : 'image/png';
const userNotes = $input.item.json['Optional Extra Instructions / Fragrance Name'] || '';

return {
  json: {
    refMime: refMime,
    refBase64: refBase64,
    userNotes: userNotes,
    totalProductImages: prodKeys.length
  },
  binary: newBinary
};

